describe("paging.next origin", () => {
  // `paging.next` is a URL taken from a response body and followed with the
  // access token attached. Meta is trusted, so this is defence in depth rather
  // than a live hole — but the cost of being wrong is handing the credential to
  // whoever the URL names, and the check is two lines.
  it("refuses to follow paging.next to another origin", async () => {
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(page([{ id: "1" }], "https://evil.example.com/steal"))

    const transport = createTransport({ accessToken: "t", fetchImpl })

    await expect(transport.getAll("/act_1/campaigns")).rejects.toThrow(/origin/i)
    // The offending request must never be made.
    expect(fetchImpl).toHaveBeenCalledTimes(1)
  })

  it("still follows paging.next on the Graph host", async () => {
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(page([{ id: "1" }], "https://graph.facebook.com/v25.0/next"))
      .mockResolvedValueOnce(page([{ id: "2" }]))

    const all = await createTransport({ accessToken: "t", fetchImpl }).getAll("/act_1/campaigns")

    expect(all).toHaveLength(2)
  })
})

describe("paging.next API version", () => {
  /**
   * Observed live on 2026-09-14, closing T-07: a request this client sent to
   * **v25.0** was answered with a `paging.next` pointing at **v26.0**. Meta
   * builds that URL, and it does not build it on the version you asked for.
   *
   * So the version pin — the whole point of which is that the API cannot move
   * under this code — silently stopped applying at page 2. Every paginated read
   * in this product crossed a version boundary mid-result.
   *
   * It is not theoretical. `COMMENT_FIELDS` already carries the note that
   * `can_hide` is absent from the v26.0 Comment node reference, so page 1 and
   * page 2 of one read could normalize different field sets with nothing
   * reporting it.
   *
   * The fixtures could never have caught this: they use
   * `https://graph.facebook.com/next-1`, which has no version segment at all.
   */
  it("replays the cursor on the pinned version, not the one Meta answers with", async () => {
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(
        page([{ id: "1" }], "https://graph.facebook.com/v26.0/123/comments?limit=100&after=CUR"),
      )
      .mockResolvedValueOnce(page([{ id: "2" }]))

    await createTransport({ accessToken: "t", fetchImpl }).getAll("/123/comments")

    const followUp = String(fetchImpl.mock.calls[1]?.[0])
    expect(followUp).toContain(`/${GRAPH_API_VERSION}/`)
    expect(followUp).not.toContain("/v26.0/")
    // The cursor is the part that must survive being rewritten. Losing it
    // re-reads page 1 forever, which the maxPages cap would end silently.
    expect(followUp).toContain("after=CUR")
  })

  it("leaves a paging.next that is already on the pinned version alone", async () => {
    const next = `https://graph.facebook.com/${GRAPH_API_VERSION}/123/comments?after=CUR`
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(page([{ id: "1" }], next))
      .mockResolvedValueOnce(page([{ id: "2" }]))

    await createTransport({ accessToken: "t", fetchImpl }).getAll("/123/comments")

    expect(String(fetchImpl.mock.calls[1]?.[0])).toBe(next)
  })
})

describe("the Graph origin override (T-43 step 2)", () => {
  /**
   * The override exists so the conformance suite can point any implementation at
   * a recorded-response stub — TypeScript can inject `fetchImpl`, Python and Go
   * cannot, and a different seam per language gives up the single definition of
   * equality the suite is for.
   *
   * What these assert is the property that makes it safe to ship: **the origin
   * requests go to and the origin `paging.next` is pinned to are one value.**
   * Configure them separately and the pin drifts off the host, which is exactly
   * the hole the 2026-09-08 review closed.
   */
  it("sends requests to the overridden origin", async () => {
    const fetchImpl = vi.fn().mockResolvedValueOnce(page([{ id: "1" }]))

    await createTransport({
      accessToken: "t",
      fetchImpl,
      graphOrigin: "http://stub.local:8080",
    }).getAll("/act_1/campaigns")

    expect(fetchImpl.mock.calls[0]?.[0]).toContain("http://stub.local:8080/v")
  })

  it("moves the paging.next pin WITH the origin, not independently of it", async () => {
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(page([{ id: "1" }], "http://stub.local:8080/v25.0/next"))
      .mockResolvedValueOnce(page([{ id: "2" }]))

    const all = await createTransport({
      accessToken: "t",
      fetchImpl,
      graphOrigin: "http://stub.local:8080",
    }).getAll("/act_1/campaigns")

    expect(all).toHaveLength(2)
  })

  it("still refuses a foreign origin when overridden — including the REAL Graph host", async () => {
    // The direction that would be easy to get wrong: pointing at a stub must not
    // make graph.facebook.com an acceptable place to send a stub's token. There
    // is one permitted origin at a time, never a permitted set.
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(page([{ id: "1" }], "https://graph.facebook.com/v25.0/next"))

    const transport = createTransport({
      accessToken: "t",
      fetchImpl,
      graphOrigin: "http://stub.local:8080",
    })

    await expect(transport.getAll("/act_1/campaigns")).rejects.toThrow(/origin/i)
    expect(fetchImpl).toHaveBeenCalledTimes(1)
  })
})
